 /**
  *	blocking_notifier_call_chain - Call functions in a blocking notifier chain
  *	@nh: Pointer to head of the blocking notifier chain
@@ -430,6 +533,57 @@ int raw_notifier_call_chain_robust(struct raw_notifier_head *nh,
